#!/usr/bin/env bash
# set -euo pipefail
export PYTORCH_CUDA_ALLOC_CONF="${PYTORCH_CUDA_ALLOC_CONF:-expandable_segments:True}"

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BASH_SCRIPTS_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"
SCRIPTS_DIR="$(cd "${BASH_SCRIPTS_DIR}/.." && pwd)"
REPO_ROOT="$(cd "${SCRIPTS_DIR}/.." && pwd)"
WORKSPACE_ROOT="$(cd "${REPO_ROOT}/.." && pwd)"

# Synthetic source data generated by synthetic_experiments_mixture_of_ranking_models.
SYNTH_DIR="${SYNTH_DIR:-${WORKSPACE_ROOT}/synthetic_experiments_mixture_of_ranking_models/mixture_of_pls/synth_data_n100k_m4_k2}"
SYNTH_TRAIN_JSONL="${SYNTH_TRAIN_JSONL:-${SYNTH_DIR}/train.jsonl}"
SYNTH_VAL_JSONL="${SYNTH_VAL_JSONL:-${SYNTH_DIR}/val.jsonl}"

# Prepared Hugging Face dataset directory consumed by scripts/dpo.py via datasets.load_from_disk.
PREP_DATASET_DIR="${PREP_DATASET_DIR:-${REPO_ROOT}/data/synth_data_n100k_m4_k2_listwise_hf}"

# For faster iteration, default to a subset. Set to 0 to use full split.
TRAIN_EXAMPLES="${TRAIN_EXAMPLES:-10000}"
EVAL_EXAMPLES="${EVAL_EXAMPLES:-1000}"

# Qwen + training defaults (override through environment variables if needed).
MODEL_NAME="${MODEL_NAME:-Qwen/Qwen3-0.6B}"
MIXTURE_REWARD_BACKEND="${MIXTURE_REWARD_BACKEND:-lora}"
MIXTURE_TRAINING_MODE="${MIXTURE_TRAINING_MODE:-em_only}"
EM_BATCHES_PER_UPDATES="${EM_BATCHES_PER_UPDATE:-8 16 32}"
EM_ALPHA_UPDATES="${EM_ALPHA_UPDATES:-block_closed_form}"
NUM_CLUSTERS="${NUM_CLUSTERS:-2}"
LISTWISE_NUM_RESPONSES="${LISTWISE_NUM_RESPONSES:-4}"
PREFERENCE_DIMENSIONS="${PREFERENCE_DIMENSIONS:-cluster_0 cluster_1}"
LEARNING_RATES="${LEARNING_RATES:-1e-5 1e-6 1e-7}"
SEEDS="${SEEDS:-42}"
MAX_STEPS="${MAX_STEPS:-1000}"
BETA="${BETA:-0.01}"
EM_TEMPERATURE="${EM_TEMPERATURE:-1.0}"
TRAIN_BATCH_SIZE="${TRAIN_BATCH_SIZE:-8}"
EVAL_BATCH_SIZE="${EVAL_BATCH_SIZE:-16}"
GRADIENT_ACCUMULATION_STEPS="${GRADIENT_ACCUMULATION_STEPS:-1}"
GRADIENT_CHECKPOINTING="${GRADIENT_CHECKPOINTING:-true}"
USE_LINEAR_REWARD_APPROX="${USE_LINEAR_REWARD_APPROX:-false}"
METRIC_FOR_BEST_MODEL="${METRIC_FOR_BEST_MODEL:-ranking_validation/mixture/cluster_acc}"
OUTPUT_ROOT="${OUTPUT_ROOT:-${REPO_ROOT}/outputs/synthetic-mixture-pl-em/qwen3-0.6b-synth-m4-k2}"
BASE_RUN_NAME="${BASE_RUN_NAME:-qwen3-0.6b-synth-m4-k2-mixture-pl-em}"
PYTHON_BIN="${PYTHON_BIN:-/home/ldy/miniconda3/envs/alignment/bin/python}"
ACCELERATE_CONFIG="${ACCELERATE_CONFIG:-recipes/accelerate_configs/single.yaml}"
EXTRA_ARGS=("$@")

export CUDA_VISIBLE_DEVICES="${CUDA_VISIBLE_DEVICES:-0}"
export WANDB_ENTITY="${WANDB_ENTITY:-nerdsresearch}"
export WANDB_PROJECT="${WANDB_PROJECT:-multimodal-preference-optimization}"
export WANDB_MODE="${WANDB_MODE:-online}"

if [[ ! -f "${SYNTH_TRAIN_JSONL}" ]]; then
  echo "Missing synthetic train file: ${SYNTH_TRAIN_JSONL}" >&2
  exit 1
fi
if [[ ! -f "${SYNTH_VAL_JSONL}" ]]; then
  echo "Missing synthetic val file: ${SYNTH_VAL_JSONL}" >&2
  exit 1
fi

export SYNTH_TRAIN_JSONL
export SYNTH_VAL_JSONL
export PREP_DATASET_DIR
export TRAIN_EXAMPLES
export EVAL_EXAMPLES

mkdir -p "${PREP_DATASET_DIR}"
mkdir -p "${OUTPUT_ROOT}"

cd "${REPO_ROOT}"
export PYTHONPATH="${REPO_ROOT}/src:${PYTHONPATH:-}"
read -r -a preference_dimension_args <<< "${PREFERENCE_DIMENSIONS}"

# Convert synthetic JSONL into preformatted listwise DatasetDict with train/test splits.
# Each example is reordered by the ground-truth ranking so response[0] is top-ranked.
"${PYTHON_BIN}" - <<'PY'
import json
import os
from datasets import Dataset, DatasetDict

synth_train = os.environ["SYNTH_TRAIN_JSONL"]
synth_val = os.environ["SYNTH_VAL_JSONL"]
out_dir = os.environ["PREP_DATASET_DIR"]
train_examples = int(os.environ["TRAIN_EXAMPLES"])
eval_examples = int(os.environ["EVAL_EXAMPLES"])


def read_jsonl(path):
    rows = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                rows.append(json.loads(line))
    return rows


def convert_row(row, row_id):
    responses = row["responses"]
    ranking = row["ranking"]
    utilities = row.get("utilities", [0.0] * len(responses))
    cluster = int(row["cluster"])

    ordered_responses = [responses[i] for i in ranking]
    ordered_scores = [float(utilities[i]) for i in ranking]

    return {
        "prompt": row["prompt"],
        "responses": ordered_responses,
        "scores": ordered_scores,
        "preference_dimension": f"cluster_{cluster}",
        "cluster": cluster,
        "source_index": row_id,
        "em_row_id": row_id,
        "ranked_prefix_length": len(ordered_responses),
    }


train_rows = [convert_row(r, idx) for idx, r in enumerate(read_jsonl(synth_train))]
val_rows = [convert_row(r, idx) for idx, r in enumerate(read_jsonl(synth_val))]

if train_examples > 0:
    train_rows = train_rows[:train_examples]
if eval_examples > 0:
    val_rows = val_rows[:eval_examples]

if len(train_rows) == 0 or len(val_rows) == 0:
    raise ValueError("Prepared train/test rows are empty. Check TRAIN_EXAMPLES/EVAL_EXAMPLES.")

cluster_values = sorted(set(r["cluster"] for r in train_rows))
print(f"Prepared train rows: {len(train_rows)}")
print(f"Prepared test rows : {len(val_rows)}")
print(f"Observed clusters  : {cluster_values}")

os.makedirs(out_dir, exist_ok=True)
ds = DatasetDict(
    {
        "train": Dataset.from_list(train_rows),
        "test": Dataset.from_list(val_rows),
    }
)
ds.save_to_disk(out_dir)
print(f"Saved converted dataset to: {out_dir}")
PY

for seed in ${SEEDS}; do
for alpha_update in ${EM_ALPHA_UPDATES}; do
for EM_BATCHES_PER_UPDATE in ${EM_BATCHES_PER_UPDATES}; do
for lr in ${LEARNING_RATES}; do
  lr_tag="${lr//./p}"
  lr_tag="${lr_tag//-/m}"
  run_name="${BASE_RUN_NAME}-${MIXTURE_REWARD_BACKEND}-${alpha_update}-emb${EM_BATCHES_PER_UPDATE}-lr${lr_tag}-s${seed}"
  output_dir="${OUTPUT_ROOT}/${MIXTURE_REWARD_BACKEND}/${alpha_update}/emb${EM_BATCHES_PER_UPDATE}-lr${lr_tag}-s${seed}"

  echo "Launching synthetic mixture PL block EM: dataset=${PREP_DATASET_DIR}; dims=${PREFERENCE_DIMENSIONS}; backend=${MIXTURE_REWARD_BACKEND}; clusters=${NUM_CLUSTERS}; alpha_update=${alpha_update}; em_batches_per_update=${EM_BATCHES_PER_UPDATE}; lr=${lr}; seed=${seed}"

  export WANDB_NAME="${run_name}"
  ACCELERATE_LOG_LEVEL=info accelerate launch \
    --config_file "${ACCELERATE_CONFIG}" \
    --num_processes="${NUM_PROCESSES:-1}" \
    scripts/dpo.py \
    --dataset_name "${PREP_DATASET_DIR}" \
    --dataset_format listwise \
    --dataset_train_split train \
    --dataset_test_split test \
    --preference_dimensions "${preference_dimension_args[@]}" \
    --listwise true \
    --listwise_num_responses "${LISTWISE_NUM_RESPONSES}" \
    --listwise_min_responses 2 \
    --run_ranking_eval true \
    --ranking_eval_during_training true \
    --model_name_or_path "${MODEL_NAME}" \
    --torch_dtype bfloat16 \
    --attn_implementation sdpa \
    --use_peft true \
    --load_in_4bit true \
    --lora_r 64 \
    --lora_alpha 64 \
    --lora_dropout 0.05 \
    --lora_target_modules q_proj k_proj v_proj o_proj gate_proj up_proj down_proj \
    --remove_unused_columns false \
    --use_mixture true \
    --mixture_objective pl \
    --num_clusters "${NUM_CLUSTERS}" \
    --mixture_nll_weight 0.1 \
    --mixture_training_mode "${MIXTURE_TRAINING_MODE}" \
    --mixture_reward_backend "${MIXTURE_REWARD_BACKEND}" \
    --em_batches_per_update "${EM_BATCHES_PER_UPDATE}" \
    --em_alpha_update "${alpha_update}" \
    --use_contextual_router false \
    --use_closed_form_router_prior_update false \
    --router_hidden_size 256 \
    --em_temperature "${EM_TEMPERATURE}" \
    --log_cluster_metrics true \
    --use_linear_reward_approx "${USE_LINEAR_REWARD_APPROX}" \
    --linear_approx_exact_eval true \
    --beta "${BETA}" \
    --learning_rate "${lr}" \
    --lr_scheduler_type cosine \
    --warmup_ratio 0.1 \
    --max_length 512 \
    --max_prompt_length 256 \
    --per_device_train_batch_size "${TRAIN_BATCH_SIZE}" \
    --per_device_eval_batch_size "${EVAL_BATCH_SIZE}" \
    --gradient_accumulation_steps "${GRADIENT_ACCUMULATION_STEPS}" \
    --gradient_checkpointing "${GRADIENT_CHECKPOINTING}" \
    --gradient_checkpointing_kwargs '{"use_reentrant": false}' \
    --eval_strategy steps \
    --eval_steps "${EVAL_STEPS:-50}" \
    --logging_steps "${LOGGING_STEPS:-10}" \
    --max_steps "${MAX_STEPS}" \
    --save_strategy steps \
    --save_steps "${SAVE_STEPS:-100}" \
    --save_total_limit 1 \
    --metric_for_best_model "${METRIC_FOR_BEST_MODEL}" \
    --output_dir "${output_dir}" \
    --run_name "${run_name}" \
    --report_to "${REPORT_TO:-wandb}" \
    --seed "${seed}" \
    --push_to_hub false \
    "${EXTRA_ARGS[@]}"
done
done
done
done

echo "Synthetic block-EM runs complete. Check ranking_validation/mixture/cluster_acc and eval_mixture/cluster_acc in W&B or saved metrics."
